-- Re-enable FK checks
SET FOREIGN_KEY_CHECKS = 1;

-- Verification Queries
SELECT 
    m.id AS medicine_id,
    m.brand_name,
    m.generic_medicine,
    COUNT(DISTINCT DATE_FORMAT(t.transaction_date, '%Y-%m')) AS months_with_history,
    SUM(di.quantity) AS total_dispensed_units,
    COUNT(di.id) AS total_dispense_records
FROM medicines m
JOIN dispensing_items di ON di.medicine_id = m.id
JOIN dispensing_transactions t ON t.id = di.transaction_id
GROUP BY m.id, m.brand_name, m.generic_medicine
ORDER BY m.id;
